/*=----------------------------------------------------------------------=*\
   Use :Reads the current sensor compass bearing based on degrees CW from magnetic north.
       :Returns 0-359 where 0 = North, 90 = East, 180 = South, 270 = West
       :Requires the ArcTan floating point function to be available to work correctly.
       :Supported on AVR, 16-bit
       :
       :Parameters for macro Read_Bearing:
       :  NumSamples : The number of readings to base the bearing on
       :
       :Returns : MX_UINT16
\*=----------------------------------------------------------------------=*/
MX_UINT16 FCD_076d1_LSM303D_Magnetometer1__Read_Bearing(MX_UINT8 FCL_NUMSAMPLES)
{
  //Local variable definitions
  MX_FLOAT FCL_FCALC;
  MX_UINT8 FCL_FX;
  MX_UINT8 FCL_FY;
  MX_UINT16 FCR_RETVAL;


  FCD_076d1_LSM303D_Magnetometer1__UpdateCompassData();

  if (FCV_076d1_LSM303D_Magnetometer1__CY == 0)
  {  

    if (FCV_076d1_LSM303D_Magnetometer1__CX < 0)
    {    

      FCR_RETVAL = 180;

    } else {

      if (FCV_076d1_LSM303D_Magnetometer1__CX > 0)
      {      

        FCR_RETVAL = 0;

      // } else {

      }

    }

  } else {

    FCL_FX = flt_toi(flt_fromi(FCV_076d1_LSM303D_Magnetometer1__CX));
    FCL_FY = flt_toi(flt_fromi(FCV_076d1_LSM303D_Magnetometer1__CY));
    FCL_FCALC = flt_fromi(FCL_FX / FCL_FY);
    FCL_FX = flt_toi(atan(FCL_FCALC));
    FCL_FCALC = flt_mul(flt_fromi(FCL_FX), FCV_076d1_LSM303D_Magnetometer1__PHI);

    if (FCV_076d1_LSM303D_Magnetometer1__CY > 0)
    {    

      FCL_FCALC = flt_sub(90.0, FCL_FCALC);

    } else {

      FCL_FCALC = flt_sub(270.0, FCL_FCALC);

    }

    FCR_RETVAL = flt_toi(FCL_FCALC);

  }

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Sets up up the communication bus and initialises the accelerometer module. 
       :Returns 1 for success and 0 for fail.
       :
       :Returns : MX_UINT8
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCD_076d1_LSM303D_Magnetometer1__Initialise()
{
  //Local variable definitions
  MX_UINT8 FCL_TEMP_REG;
  MX_UINT8 FCR_RETVAL;


  FCI_DELAYBYTE_MS(100);

  FC_CAL_I2C_Master_Init_1();

  FCV_076d1_LSM303D_Magnetometer1__CURRENT_ADDRESS = FCV_076d1_LSM303D_Magnetometer1__ACCEL_ADDRESS;

  FCL_TEMP_REG = FCD_076d1_LSM303D_Magnetometer1__Read_Register(0x0F);

  if (FCL_TEMP_REG == 0x49)
  {  

    FCR_RETVAL = 1;

    FCD_076d1_LSM303D_Magnetometer1__Write_Register(0x12, 0);

    FCL_TEMP_REG = 7 << 4;
    FCL_TEMP_REG = FCL_TEMP_REG | 0x07;

    FCD_076d1_LSM303D_Magnetometer1__Write_Register(0x20, FCL_TEMP_REG);

    FCL_TEMP_REG = 0 << 3;

    FCD_076d1_LSM303D_Magnetometer1__Write_Register(0x21, FCL_TEMP_REG);

    FCD_076d1_LSM303D_Magnetometer1__Write_Register(0x22, 0);

    FCD_076d1_LSM303D_Magnetometer1__Write_Register(0x23, 0);

    FCL_TEMP_REG = 3 << 2;
    FCL_TEMP_REG = FCL_TEMP_REG | 0x80;

    FCD_076d1_LSM303D_Magnetometer1__Write_Register(0x24, FCL_TEMP_REG);

    FCL_TEMP_REG = 0 << 5;

    FCD_076d1_LSM303D_Magnetometer1__Write_Register(0x25, FCL_TEMP_REG);

    FCD_076d1_LSM303D_Magnetometer1__Write_Register(0x26, 0x80);

    FCV_076d1_LSM303D_Magnetometer1__CX = 0;
    FCV_076d1_LSM303D_Magnetometer1__CY = 0;
    FCV_076d1_LSM303D_Magnetometer1__CZ = 0;

  } else {

    FCR_RETVAL = 0;

  }

  return (FCR_RETVAL);

}


