/*=----------------------------------------------------------------------=*\
   Use :Clear one page of flash memory
       :
       :Parameters for macro ClearPage:
       :  pageNumber : The page to be cleared
\*=----------------------------------------------------------------------=*/
void FCD_0f151_flashio1__ClearPage(MX_UINT8 FCL_PAGENUMBER)
{
  //Local variable definitions
  MX_UINT32 FCL_MEMADDRESS;


  #if (1) // 131072 != 0
    FCL_MEMADDRESS = 131072 + (512 * FCL_PAGENUMBER);

  #else
  //Code has been optimised out by the pre-processor
  #endif

  #if (1)
    {
    // Calculate address and set registers
    MX_UINT16 addr = (FCL_MEMADDRESS & 0xffff);
    MX_UINT16 savesr;

    // Set address of page to clear
    NVMADRU = ((FCL_MEMADDRESS & 0x7f0000) >> 16);
    NVMADR = addr;

    // Save interrupt register and disable interrupts
    savesr = SR;
    SR = SR | 0xE0;

    // Set programming mode to WORD programming
    NVMCON = _FLASH_ERASE_CODE;

    // Write to flash
    __builtin_write_NVM();

    // Reenable interrupts
    SR = savesr;

    // Wait for operation to complete
    while (NVMCON & 0x8000) ;
    }

  #else
  //Code has been optimised out by the pre-processor
  #endif

}

/*=----------------------------------------------------------------------=*\
   Use :Read address and data from specified page and cell position
       :
       :Parameters for macro ReadCell:
       :  page : MX_UINT8
       :  cell : MX_UINT8
       :
       :Returns : MX_UINT32
\*=----------------------------------------------------------------------=*/
MX_UINT32 FCD_0f151_flashio1__ReadCell(MX_UINT8 FCL_PAGE, MX_UINT8 FCL_CELL)
{
  //Local variable definitions
  MX_UINT32 FCL_MEMADDRESS;
  MX_UINT32 FCR_RETVAL;


  #if (1) // 131072 != 0
    FCL_MEMADDRESS = 131072 + (512 * FCL_PAGE) + (2 * FCL_CELL);

  #else
  //Code has been optimised out by the pre-processor
  #endif

  {
  // Calculate address and set registers
  MX_UINT8 savetbl = TBLPAG;
  MX_UINT16 addr = (FCL_MEMADDRESS & 0xffff);

  TBLPAG = ((FCL_MEMADDRESS & 0x7f0000) >> 16);

  // Read values
  FCR_RETVAL = __builtin_tblrdh(addr);
  FCR_RETVAL = FCR_RETVAL << 16;
  FCR_RETVAL |= __builtin_tblrdl(addr) & 0xffff;

  // restore TBLPAG
  TBLPAG = savetbl;
  }

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Write address and data to specified page and cell position
       :
       :Parameters for macro WriteCell:
       :  page : MX_UINT8
       :  cell : MX_UINT8
       :  address : MX_UINT8
       :  value : MX_UINT16
\*=----------------------------------------------------------------------=*/
void FCD_0f151_flashio1__WriteCell(MX_UINT8 FCL_PAGE, MX_UINT8 FCL_CELL, MX_UINT8 FCL_ADDRESS, MX_UINT16 FCL_VALUE)
{
  //Local variable definitions
  MX_UINT32 FCL_MEMADDRESS;


  #if (1) // 131072 != 0
    FCL_MEMADDRESS = 131072 + (512 * FCL_PAGE) + (2 * FCL_CELL);

  #else
  //Code has been optimised out by the pre-processor
  #endif

  #if (1)
    {
    #ifndef _FLASH_WRITE_WORD_CODE
    #error "Controller not supported by FLASH EEPROM emulation"
    #endif

    //#warning "The flash emulation component for dsPIC33E and PIC24E devices MAY NOT work"
    //#warning "depending on the device used. Test carefully!!"

    // Calculate address and set registers
    MX_UINT8 savetbl = TBLPAG;
    MX_UINT16 addr = (FCL_MEMADDRESS & 0xffff);
    MX_UINT8 savebyte;
    MX_UINT16 saveword;
    MX_UINT16 savesr;

    // calculate page register
    TBLPAG = ((FCL_MEMADDRESS & 0x7f0000) >> 16);

    // Set destination address for flash write
    NVMADRU = TBLPAG;
    NVMADR = (addr & 0b1111111111111100);

    // Read values of other word
    addr = addr ^ 0x02;
    savebyte = __builtin_tblrdh(addr);
    saveword = __builtin_tblrdl(addr);

    // Truncate address to last few bits
    addr = addr & 0x3;

    // Set TBLPAG to flash programming latch
    TBLPAG = 0xFA;

    // Store saved values to programming latch
    __builtin_tblwtl(addr, saveword);
    __builtin_tblwth(addr, savebyte);

    addr = addr ^ 0x02;

    // Store values
    __builtin_tblwtl(addr, FCL_VALUE);
    __builtin_tblwth(addr, FCL_ADDRESS);


    // Set programming mode to (double) WORD programming
    NVMCON = _FLASH_WRITE_WORD_CODE;

    // disable interrupts
    savesr = SR;
    SR = SR | 0xE0;

    // Write to flash
    __builtin_write_NVM();
    //asm("mov #0x55,W0");
    //asm("mov W0, NVMKEY");
    //asm("mov #0xAA,W0");
    //asm("mov W0,NVMKEY");
    //asm("mov #0xC001,W0");
    //asm("mov W1,NVMCON");
    //asm("bset NVMCON,#15");
    asm("nop");
    asm("nop");
    asm("wr_lbl_aaa: btsc NVMCON, #15");
    asm("BRA wr_lbl_aaa");

    SR = savesr;

    // restore TBLPAG
    TBLPAG = savetbl;
    }

  #else
  //Code has been optimised out by the pre-processor
  #endif

}


