/*=----------------------------------------------------------------------=*\
   Use :This macro clears the display of any previous output by overwriting the entire display with the background colour.
\*=----------------------------------------------------------------------=*/
void FCD_0ab21_gLCD_ST7567_SPI1__ClearDisplay()
{
  //Local variable definitions
  MX_UINT16 FCL_Y = (0x0);
  MX_UINT16 FCL_X = (0x0);


  while (FCL_X < 512)
  {
    FCV_0ab21_gLCD_ST7567_SPI1__LCD_DATA[FCL_X] = FCV_0ab21_gLCD_ST7567_SPI1__BACKGROUND_COL_VAR;

    FCL_X = FCL_X + 1;

  }

  while (FCL_Y < (32 / 8))
  {
    FCL_X = 0;

    while (FCL_X < 128)
    {
      FCD_0ab21_gLCD_ST7567_SPI1__Goto_XY(FCL_X, FCL_Y * 8);

      FCD_0ab21_gLCD_ST7567_SPI1__Write_Data(FCV_0ab21_gLCD_ST7567_SPI1__BACKGROUND_COL_VAR);

      FCL_X = FCL_X + 1;

    }

    FCL_Y = FCL_Y + 1;

  }

}

