/*=----------------------------------------------------------------------=*\
   Use :Draws a rectangle with the current foreground colour from pixel loaction X1, Y1 to pixel location X2, Y2
       :
       :Parameters for macro DrawRectangle:
       :  X1 : MX_UINT16
       :  Y1 : MX_UINT16
       :  X2 : MX_UINT16
       :  Y2 : MX_UINT16
       :  Transparent : MX_UINT8
       :  Solid : MX_UINT8
\*=----------------------------------------------------------------------=*/
void FCD_0ab21_gLCD_ST7567_SPI1__DrawRectangle(MX_UINT16 FCL_X1, MX_UINT16 FCL_Y1, MX_UINT16 FCL_X2, MX_UINT16 FCL_Y2, MX_UINT8 FCL_TRANSPARENT, MX_UINT8 FCL_SOLID)
{
  //Local variable definitions
  MX_UINT8 FCL_XMAX;
  MX_UINT8 FCL_XMIN;
  MX_UINT8 FCL_YMAX;
  MX_UINT8 FCL_YMIN;


  FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_X1, FCL_Y1, FCL_X2, FCL_Y1);

  FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_X2, FCL_Y1, FCL_X2, FCL_Y2);

  FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_X1, FCL_Y2, FCL_X2, FCL_Y2);

  FCD_0ab21_gLCD_ST7567_SPI1__DrawLine(FCL_X1, FCL_Y1, FCL_X1, FCL_Y2);

  if (FCL_TRANSPARENT == 0)
  {  

    if (FCL_X1 > FCL_X2)
    {    

      FCL_XMAX = FCL_X1;
      FCL_XMIN = FCL_X2 + 1;

    } else {

      FCL_XMAX = FCL_X2;
      FCL_XMIN = FCL_X1 + 1;

    }

    if (FCL_Y1 > FCL_Y2)
    {    

      FCL_YMAX = FCL_Y1;
      FCL_YMIN = FCL_Y2 + 1;

    } else {

      FCL_YMAX = FCL_Y2;
      FCL_YMIN = FCL_Y1 + 1;

    }

    FCL_Y1 = FCL_YMIN;

    while (FCL_Y1 < FCL_YMAX)
    {
      FCL_X1 = FCL_XMIN;

      while (FCL_X1 < FCL_XMAX)
      {
        if (FCL_SOLID)
        {        

          FCD_0ab21_gLCD_ST7567_SPI1__Plot(FCL_X1, FCL_Y1);

        } else {

          FCD_0ab21_gLCD_ST7567_SPI1__BPlot(FCL_X1, FCL_Y1);

        }

        FCL_X1 = FCL_X1 + 1;

      }

      FCL_Y1 = FCL_Y1 + 1;

    }

  // } else {

  }

}

