/*=----------------------------------------------------------------------=*\
   Use :Outputs a single tone from the onboard speaker for the period specified.
       :
       :Parameters for macro PlayNote:
       :  Note : Sets the pitch of the note in Hz. Range: 1 - 10000
       :  Time : Time period to play the note for in milliseconds. Range: 0 - 65535 ms
\*=----------------------------------------------------------------------=*/
void FCD_0dcd1_FormulaAllcode1__PlayNote(MX_UINT16 FCL_NOTE, MX_UINT16 FCL_TIME)
{
  //Local variable definitions
  MX_UINT32 FCL_LOOP = (0x0);
  MX_UINT16 FCL_TRANSFREQ;
  MX_FLOAT FCL_TRANSDELAY;
  MX_UINT16 FCL_DELAY;
  MX_UINT32 FCL_LOOPCOUNT;
  MX_FLOAT FCL_TEMP;


  if (FCL_NOTE < 10)
  {  

    FCL_NOTE = 10;

  // } else {

  }

  if (FCL_TIME < 5)
  {  

    FCL_TIME = 5;

  // } else {

  }

  FCL_TRANSFREQ = (2 * FCL_NOTE);
  FCL_TRANSDELAY = (flt_div(1.0, flt_fromi(FCL_TRANSFREQ)));

  FCL_DELAY = flt_toi((flt_mul(FCL_TRANSDELAY, 1000000.0)));

  FCL_TEMP = (flt_mul((flt_mul(2.0, FCL_TRANSDELAY)), 1000.0));

  if (flt_lt(FCL_TEMP, 0.000001))
  {  

    FCL_TEMP = 0.000001;

  // } else {

  }

  FCL_LOOPCOUNT = flt_toi(flt_div(flt_fromi(FCL_TIME), FCL_TEMP));

  SET_PORT_PIN(F,3,(0));

  FCL_LOOP = 0;

  while (FCL_LOOP < FCL_LOOPCOUNT)
  {
    FCI_DELAYINT_US(FCL_DELAY);

    SET_PORT_PIN(F,3,(1));

    FCI_DELAYINT_US(FCL_DELAY);

    SET_PORT_PIN(F,3,(0));

    FCL_LOOP = FCL_LOOP + 1;

  }

}

