/*=----------------------------------------------------------------------=*\
   Use :Switches off a single LED on the front of the Formula Allcode.
       :
       :Parameters for macro LEDOff:
       :  LED : Which LED to switch on, range 0-7
\*=----------------------------------------------------------------------=*/
void FCD_0dcd1_FormulaAllcode1__LEDOff(MX_UINT8 FCL_LED)
{

  switch (FCL_LED)
  {
    case 0:
    {

      SET_PORT_PIN(E,0,(0));

      break;
    }
    case 1:
    {

      SET_PORT_PIN(E,1,(0));

      break;
    }
    case 2:
    {

      SET_PORT_PIN(E,2,(0));

      break;
    }
    case 3:
    {

      SET_PORT_PIN(E,3,(0));

      break;
    }
    case 4:
    {

      SET_PORT_PIN(E,4,(0));

      break;
    }
    case 5:
    {

      SET_PORT_PIN(E,5,(0));

      break;
    }
    case 6:
    {

      SET_PORT_PIN(E,6,(0));

      break;
    }
    case 7:
    {

      SET_PORT_PIN(E,7,(0));

      break;
    }
    // default:

  }

}

