/*=----------------------------------------------------------------------=*\
   Use :Rotates the robot left by a specific angle using the encoders as feedback to ensure
       :the robot turns evenly. Automatically stops at the specified turn angle.
       :
       :Parameters for macro LogoTurnLeft:
       :  Angle : Angle in degrees you wish to rotate. Range 1-65536
\*=----------------------------------------------------------------------=*/
void FCD_0dcd1_FormulaAllcode1__LogoTurnLeft(MX_UINT16 FCL_ANGLE)
{
  //Local variable definitions
  MX_UINT32 FCL_ENCTARGET;
  MX_FLOAT FCL_FCALC;


  FCL_FCALC = flt_fromi(FCL_ANGLE);
  FCL_FCALC = flt_mul(FCL_FCALC, FCV_0dcd1_FormulaAllcode1__ANGLERESOLUTION);
  FCL_FCALC = flt_div(FCL_FCALC, FCV_0dcd1_FormulaAllcode1__ENCODERRESOLUTION);
  FCL_FCALC = flt_mul(FCL_FCALC, 0.880000);
  FCL_ENCTARGET = flt_toi(FCL_FCALC);

  FCD_0dcd1_FormulaAllcode1__LogoProcess2(-(FCV_0dcd1_FormulaAllcode1__LOGOSPEED * 3) / 4, (FCV_0dcd1_FormulaAllcode1__LOGOSPEED * 3) / 4, FCL_ENCTARGET);

}

