/*=----------------------------------------------------------------------=*\
   Use :Sets the speed and direction of the Formula Allcode motors.
       :
       :Parameters for macro SetMotorsInterrupt:
       :  Left : Valid Range = -100 to 100
       :  Right : Valid Range = -100 to 100
\*=----------------------------------------------------------------------=*/
void FCD_0dcd1_FormulaAllcode1__SetMotorsInterrupt(MX_SINT16 FCL_LEFT, MX_SINT16 FCL_RIGHT)
{
  //Local variable definitions
  MX_UINT8 FCL_MASK = (0x0);


  OC1CON1 = 0;
  OC2CON1 = 0;
  OC5CON1 = 0;
  OC6CON1 = 0;

  if (FCL_LEFT == 0)
  {  

    FCV_0dcd1_FormulaAllcode1__LEFT = 0;

#if 0 // Disabled code
    SET_PORT_MASK(D,0x0003,(0x03));

#endif // Disabled code

    SET_PORT_MASK(D,0x0003,(0));

  } else {

    FCL_MASK = FCL_MASK | 1;

    if (FCL_LEFT >= 0)
    {    

      FCV_0dcd1_FormulaAllcode1__LEFT = FCL_LEFT;

      FCV_0dcd1_FormulaAllcode1__LEFTDIR = 0;

      FC_CAL_PWM_Enable_3();

      FC_CAL_PWM_SetDuty8Bit_3(FCV_0dcd1_FormulaAllcode1__LEFT);

    } else {

      FCV_0dcd1_FormulaAllcode1__LEFT = 0 - FCL_LEFT;

      FCV_0dcd1_FormulaAllcode1__LEFTDIR = 1;

      FC_CAL_PWM_Enable_2();

      FC_CAL_PWM_SetDuty8Bit_2(FCV_0dcd1_FormulaAllcode1__LEFT);

    }

    SET_PORT_MASK(D,0x0003,(0));

  }

  if (FCL_RIGHT == 0)
  {  

    FCV_0dcd1_FormulaAllcode1__RIGHT = 0;

#if 0 // Disabled code
    SET_PORT_MASK(D,0x000C,(0x0C));

#endif // Disabled code

    SET_PORT_MASK(D,0x000C,(0));

  } else {

    FCL_MASK = FCL_MASK | 2;

    if (FCL_RIGHT >= 0)
    {    

      FCV_0dcd1_FormulaAllcode1__RIGHT = FCL_RIGHT;

      FCV_0dcd1_FormulaAllcode1__RIGHTDIR = 0;

      FC_CAL_PWM_Enable_5();

      FC_CAL_PWM_SetDuty8Bit_5(FCV_0dcd1_FormulaAllcode1__RIGHT);

    } else {

      FCV_0dcd1_FormulaAllcode1__RIGHT = 0 - FCL_RIGHT;

      FCV_0dcd1_FormulaAllcode1__RIGHTDIR = 1;

      FC_CAL_PWM_Enable_4();

      FC_CAL_PWM_SetDuty8Bit_4(FCV_0dcd1_FormulaAllcode1__RIGHT);

    }

    SET_PORT_MASK(D,0x000C,(0));

  }

}

