/*=----------------------------------------------------------------------=*\
   Use :Waits for the specified switch to be pressed.
       :
       :Parameters for macro WaitForSwitch:
       :  Switch : Which switch do we want to wait for 0=Left, 1=Right, 2=Either, 3=Both
\*=----------------------------------------------------------------------=*/
void FCD_0dcd1_FormulaAllcode1__WaitForSwitch(MX_UINT8 FCL_SWITCH)
{
  //Local variable definitions
  MX_UINT8 FCL_DONE = (0x0);
  MX_UINT8 FCL_TEMP;


  while (FCL_DONE == 0)
  {
    switch (FCL_SWITCH)
    {
      case 1:
      {

        FCL_DONE = GET_PORT_PIN(A,1);

        break;
      }
      case 2:
      {

        FCL_DONE = GET_PORT_MASK(A,0x0003);

        break;
      }
      case 3:
      {

        FCL_TEMP = GET_PORT_MASK(A,0x0003);

        if (FCL_TEMP == 3)
        {        

          FCL_DONE = 1;

        // } else {

        }

        break;
      }
      default:
      {
        FCL_DONE = GET_PORT_PIN(A,0);

      }
    }

  }

}

