/*=----------------------------------------------------------------------=*\
   Use :Starts up the Formula Allcode PWM for motor control and performs the wait for button press if enabled.
\*=----------------------------------------------------------------------=*/
void FCD_0dcd1_FormulaAllcode1__Initialise()
{
  //Local variable definitions
  MX_UINT8 FCL_SW = (0x0);
  #define FCLsz_CMD 20
  MX_CHAR FCL_CMD[FCLsz_CMD];
  MX_UINT16 FCL_TEST;


  FCL_SW = 0;
  FCI_SCOPY("",1, FCL_CMD,FCLsz_CMD);

  FCV_0dcd1_FormulaAllcode1__RESETCOUNT = 0;
  FCV_0dcd1_FormulaAllcode1__AREYOUTHERECOUNT = 0;
  FCV_0dcd1_FormulaAllcode1__CMDACTIVE = 0;

  FCI_DELAYBYTE_MS(10);

  //Comment:
  //Initialise Motors

  SET_PORT_MASK(D,0x000F,(0x00));

  FC_CAL_PWM_ChangePeriod_2(100, 8);

  SET_PORT_PIN(G,7,(1));

  // ::Connection.SetAn(21, 0.606, 0)

  //Comment:
  //Initialise LCD

  FCD_0ab21_gLCD_ST7567_SPI1__Initialise();

  FCD_0ab21_gLCD_ST7567_SPI1__ClearDisplay();

  FCD_0ab21_gLCD_ST7567_SPI1__Print("Formula AllCode", 16, 18, 0, 0, 0);

  #if (0) // (0 == 2) | (0 == 3)
  //Code has been optimised out by the pre-processor
  // #else
  #endif

  #if (0) // (0 == 1) | (0 == 3)
  //Code has been optimised out by the pre-processor
  // #else
  #endif

#if 0 // Disabled code
  FCD_0dcd1_FormulaAllcode1__BattMon();

#endif // Disabled code

  //Comment:
  //Initialise backlight

  FCD_0dcd1_FormulaAllcode1__LCDBacklight(50);

  FCD_06b71_BlueTooth__Initialise();

  //Comment:
  //Enable Interrupts

  FCV_0dcd1_FormulaAllcode1__ENCSAVE = GET_PORT(B) >> 11;

  // Bluetooth RX Interrupt Enable
  // Interrupt: Enable RXINT0
  IEC0bits.U1RXIE = 1;

  // Encoder Interrupt Enable
  // Interrupt: Enable IOC0
  CNENA = 0x0;
  CNENB = 0x1800;
  CNENC = 0x0;
  CNEND = 0x0;
  CNENE = 0x0;
  CNENF = 0x0;
  CNENG = 0x0;
  IEC1bits.CNIE = 1;

  //Comment:
  //Restore Logo Resultion From Flash EE memory

  FCD_0ee91_flasheeprom1__Initialise();

  FCL_TEST = FCD_0ee91_flasheeprom1__Read(20);

  if (FCL_TEST == 0)
  {  

    FCV_0dcd1_FormulaAllcode1__ENCODERRESOLUTION = FCD_0dcd1_FormulaAllcode1__GetEEFloat(0);

    FCV_0dcd1_FormulaAllcode1__ANGLERESOLUTION = FCD_0dcd1_FormulaAllcode1__GetEEFloat(10);

    FCD_0dcd1_FormulaAllcode1__Prv_LoadMotorCal();

  // } else {

  }

  //Comment:
  //Wait for switch

  #if (0) // 0 == 1
  //Code has been optimised out by the pre-processor
  #else
    FCI_DELAYINT_MS(2000);

  #endif

  FCD_0ab21_gLCD_ST7567_SPI1__ClearDisplay();

  FCD_0dcd1_FormulaAllcode1__LCDBacklight(0);

  #if (0)
  //Code has been optimised out by the pre-processor
  // #else
  #endif

  //Local variable definitions
  #undef FCLsz_CMD
}

