/*=----------------------------------------------------------------------=*\
   Use :Adds a single byte to the end of the currently open file, useful for inserting the value 0 into binary file types.
       :Returns 0 for success.
       :
       :Parameters for macro AppendByteToFile:
       :  Data : Data to append to the end of the file
       :
       :Returns : MX_UINT8
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCD_07fa1_FAT1__AppendByteToFile(MX_UINT8 FCL_DATA)
{
  //Local variable definitions
  MX_UINT8 FCL_IDX;
  MX_SINT16 FCL_LENGTH;
  MX_UINT8 FCL_OFFSET = (0x0);
  MX_UINT16 FCL_IDX16;
  MX_UINT8 FCL_STR_LEN;
  MX_UINT8 FCL_J;
  MX_UINT8 FCR_RETVAL;


  FCL_STR_LEN = 1;

  FCL_LENGTH = FCD_07fa1_FAT1__ReadFileLength();

  while (FCL_LENGTH == 512)
  {
    FCR_RETVAL = FCD_07fa1_FAT1__Read_Next_File_Sector();

    if (FCR_RETVAL == 0x01)
    {    

      FCL_LENGTH = -1;

    } else {

      FCL_LENGTH = FCD_07fa1_FAT1__ReadFileLength();

    }

  }

  if (FCL_LENGTH == -1)
  {  

    FCL_LENGTH = 512;

  // } else {

  }

  FCL_IDX = 0;

  while (FCL_IDX < FCL_STR_LEN)
  {
    if ((FCL_LENGTH + FCL_IDX) == 512)
    {    

      FCL_LENGTH = 0;

      FCL_OFFSET = FCL_IDX;

      FCD_07fa1_FAT1__SendBuffer(FCV_07fa1_FAT1__FILE_POINTER[FCV_07fa1_FAT1__FILE_IDX]);

      FCR_RETVAL = FCD_07fa1_FAT1__Read_Next_File_Sector();

      if (FCR_RETVAL == 0x01)
      {      

        FCD_07fa1_FAT1__Add_Sector_To_File();

      } else {

        if (FCR_RETVAL > 0x01)
        {        

          goto FCC_AppendByteToFile_A;

        // } else {

        }

      }

    // } else {

    }

    FCD_07fa1_FAT1__WriteByteToBuffer(FCL_LENGTH + (FCL_IDX - FCL_OFFSET), FCL_DATA);

    FCL_IDX = FCL_IDX + 1;

  }

  FCD_07fa1_FAT1__SendBuffer(FCV_07fa1_FAT1__FILE_POINTER[FCV_07fa1_FAT1__FILE_IDX]);

  FCV_07fa1_FAT1__FILE_SIZE[FCV_07fa1_FAT1__FILE_IDX] = FCV_07fa1_FAT1__FILE_SIZE[FCV_07fa1_FAT1__FILE_IDX] + FCL_STR_LEN;

  FCD_07fa1_FAT1__GetBuffer(FCV_07fa1_FAT1__FILE_ADDRESS[FCV_07fa1_FAT1__FILE_IDX]);

  FCL_IDX16 = 28 + (FCV_07fa1_FAT1__FILE_ENTRY[FCV_07fa1_FAT1__FILE_IDX] << 5);

  FCD_08941_TypeConversions1__SetLong(FCV_07fa1_FAT1__FILE_SIZE[FCV_07fa1_FAT1__FILE_IDX]);

  FCL_J = FCD_08941_TypeConversions1__GetByte(0);

  FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX16, FCL_J);

  FCL_J = FCD_08941_TypeConversions1__GetByte(1);

  FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX16 + 1, FCL_J);

  FCL_J = FCD_08941_TypeConversions1__GetByte(2);

  FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX16 + 2, FCL_J);

  FCL_J = FCD_08941_TypeConversions1__GetByte(3);

  FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX16 + 3, FCL_J);

  FCD_07fa1_FAT1__SendBuffer(FCV_07fa1_FAT1__FILE_ADDRESS[FCV_07fa1_FAT1__FILE_IDX]);

#if 0 // Disabled code
  FCD_07fa1_FAT1__SendBuffer(FCV_07fa1_FAT1__FILE_ADDRESS[FCV_07fa1_FAT1__FILE_IDX] + FCV_07fa1_FAT1__FAT_SIZE);

#endif // Disabled code

  FCD_07fa1_FAT1__GetBuffer(FCV_07fa1_FAT1__FILE_POINTER[FCV_07fa1_FAT1__FILE_IDX]);

  FCR_RETVAL = FCV_07fa1_FAT1__ACK_OK;

FCC_AppendByteToFile_A:
  ;

  return (FCR_RETVAL);

}

