/*=----------------------------------------------------------------------=*\
   Use :Overwrites the current sector on the memory card with the contents of the local sector buffer. See write_byte_to_buffer function.
       :Return = 0 - File sector written successfully.
       :Return > 0 - File sector write error
       :
       :Returns : MX_UINT8
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCD_07fa1_FAT1__WriteFileSector()
{
  //Local variable definitions
  MX_UINT16 FCL_IDX;
  MX_UINT32 FCL_TEMP;
  MX_UINT8 FCL_J;
  MX_UINT8 FCR_RETVAL;


  FCL_TEMP = FCV_07fa1_FAT1__FILE_SIZE[FCV_07fa1_FAT1__FILE_IDX] >> 9;

  if (FCL_TEMP == FCV_07fa1_FAT1__FILE_SECTOR[FCV_07fa1_FAT1__FILE_IDX] - 1)
  {  

    FCL_TEMP = FCD_07fa1_FAT1__ReadFileLength();

    FCL_TEMP = 512 - FCL_TEMP;

    FCV_07fa1_FAT1__FILE_SIZE[FCV_07fa1_FAT1__FILE_IDX] = FCV_07fa1_FAT1__FILE_SIZE[FCV_07fa1_FAT1__FILE_IDX] + FCL_TEMP;

  // } else {

  }

  FCD_07fa1_FAT1__SendBuffer(FCV_07fa1_FAT1__FILE_POINTER[FCV_07fa1_FAT1__FILE_IDX]);

  FCD_07fa1_FAT1__GetBuffer(FCV_07fa1_FAT1__FILE_ADDRESS[FCV_07fa1_FAT1__FILE_IDX]);

  FCL_IDX = 28 + (FCV_07fa1_FAT1__FILE_ENTRY[FCV_07fa1_FAT1__FILE_IDX] << 5);

  FCD_08941_TypeConversions1__SetLong(FCV_07fa1_FAT1__FILE_SIZE[FCV_07fa1_FAT1__FILE_IDX]);

  FCL_J = FCD_08941_TypeConversions1__GetByte(0);

  FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX, FCL_J);

  FCL_J = FCD_08941_TypeConversions1__GetByte(1);

  FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX + 1, FCL_J);

  FCL_J = FCD_08941_TypeConversions1__GetByte(2);

  FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX + 2, FCL_J);

  FCL_J = FCD_08941_TypeConversions1__GetByte(3);

  FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX + 3, FCL_J);

  FCD_07fa1_FAT1__SendBuffer(FCV_07fa1_FAT1__FILE_ADDRESS[FCV_07fa1_FAT1__FILE_IDX]);

  //Comment:
  //This gets the current file sector data which may be unnessisary.
  //We leave it in for now just incase.

  FCD_07fa1_FAT1__GetBuffer(FCV_07fa1_FAT1__FILE_POINTER[FCV_07fa1_FAT1__FILE_IDX]);

  FCR_RETVAL = FCV_07fa1_FAT1__ACK_OK;

  return (FCR_RETVAL);

}

