/*=----------------------------------------------------------------------=*\
   Use :Parameters for macro Format_File_String:
       :  Filename[13] : MX_CHAR (by-ref)
\*=----------------------------------------------------------------------=*/
void FCD_07fa1_FAT1__Format_File_String(MX_CHAR *FCL_FILENAME, MX_UINT16 FCLsz_FILENAME)
{
  //Local variable definitions
  MX_UINT8 FCL_I;
  MX_UINT8 FCL_J;
  #define FCLsz_FILENAME_COPY 13
  MX_CHAR FCL_FILENAME_COPY[FCLsz_FILENAME_COPY];


  FCL_I = 0;

  while (FCL_I < 11)
  {
    FCV_07fa1_FAT1__NAME_EXT[FCL_I] = 0x20;

    FCL_I = FCL_I + 1;

  }

  FCV_07fa1_FAT1__NAME_EXT[11] = 0;

  FCI_TOUPPER(FCL_FILENAME, FCLsz_FILENAME, FCL_FILENAME_COPY,13);

  FCL_I = 0;

  while (FCL_I < 8)
  {
    if (FCL_FILENAME_COPY[FCL_I] == '.')
    {    

      goto FCC_Format_File_String_A;

    // } else {

    }

    if (FCL_FILENAME_COPY[FCL_I] == 0)
    {    

      goto FCC_Format_File_String_A;

    // } else {

    }

    FCV_07fa1_FAT1__NAME_EXT[FCL_I] = FCL_FILENAME_COPY[FCL_I];

    FCL_I = FCL_I + 1;

  }

FCC_Format_File_String_A:
  ;

  if (FCL_FILENAME_COPY[FCL_I] == '.')
  {  

    FCL_J = FCL_I + 1;

    FCL_I = 8;

    while (FCL_I < 11)
    {
      if (FCL_FILENAME_COPY[FCL_J] == 0)
      {      

        goto FCC_Format_File_String_B;

      // } else {

      }

      FCV_07fa1_FAT1__NAME_EXT[FCL_I] = FCL_FILENAME_COPY[FCL_J];

      FCL_I = FCL_I + 1;
      FCL_J = FCL_J + 1;

    }

  // } else {

  }

FCC_Format_File_String_B:
  ;

  //Local variable definitions
  #undef FCLsz_FILENAME_COPY
}

