    FCL_I = FCD_07fa1_FAT1__ReadByteFromBuffer(0x24);

    FCD_08941_TypeConversions1__SetByte(0, FCL_I);

    FCL_I = FCD_07fa1_FAT1__ReadByteFromBuffer(0x25);

    FCD_08941_TypeConversions1__SetByte(1, FCL_I);

    FCL_I = FCD_07fa1_FAT1__ReadByteFromBuffer(0x26);

    FCD_08941_TypeConversions1__SetByte(2, FCL_I);

    FCL_I = FCD_07fa1_FAT1__ReadByteFromBuffer(0x27);

