/*=----------------------------------------------------------------------=*\
   Use :
\*=----------------------------------------------------------------------=*/
void FCM_TestCompass()
{
  //Local variable definitions
  MX_SINT16 FCL_X;
  MX_SINT16 FCL_Y;
  MX_SINT16 FCL_Z;
  MX_SINT16 FCL_DIFX;
  MX_SINT16 FCL_DIFY;
  MX_SINT16 FCL_DIFZ;


#if 0 // Disabled code
  // Call Component Macro
  FCV_DONE = FCD_076d1_LSM303D_Magnetometer1__Initialise();

#endif // Disabled code

  // Call Component Macro
  FCD_0dcd1_FormulaAllcode1__LCDClear();

  // Call Component Macro
  FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 0, "Orientation:", 13, 0);

  // Decision
  if (FCV_ACCELTYPE)
  {  

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 8, "LIS3DHTR", 9, 0);

  } else {

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 8, "LSM303D", 8, 0);

  }

  // Calculation
  FCV_COUNT = 0;

  // Calculation
  FCV_DONE = 0;

  // Loop
  while (FCV_DONE == 0)
  {
    // Decision
    if (FCV_ACCELTYPE)
    {    

      // Call Component Macro
      FCD_0ab41_LIS3DHTR_Accelerometer1__UpdateAccelerometerData();

      // Call Component Macro
      FCL_X = FCD_0ab41_LIS3DHTR_Accelerometer1__CollectXYZData(0);

      // Call Component Macro
      FCL_Y = FCD_0ab41_LIS3DHTR_Accelerometer1__CollectXYZData(1);

      // Call Component Macro
      FCL_Z = FCD_0ab41_LIS3DHTR_Accelerometer1__CollectXYZData(2);

    } else {

      // Call Component Macro
      FCD_076d1_LSM303D_Magnetometer1__UpdateAccelerometerData();

      // Call Component Macro
      FCL_X = FCD_076d1_LSM303D_Magnetometer1__CollectXYZData(0);

      // Call Component Macro
      FCL_Y = FCD_076d1_LSM303D_Magnetometer1__CollectXYZData(1);

      // Call Component Macro
      FCL_Z = FCD_076d1_LSM303D_Magnetometer1__CollectXYZData(2);

    }

    // Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDSetForegroundColour(0);

    // Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDDrawRectangle(0, 24, 127, 31, 0, 1);

    // Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDSetForegroundColour(255);

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintNumber(0, 24, FCL_X, 0);

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintNumber(42, 24, FCL_Y, 0);

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintNumber(84, 24, FCL_Z, 0);

    // Decision
    if (FCL_X < 0)
    {    

      // Calculation
      FCL_DIFX = -FCL_X;

    } else {

      // Calculation
      FCL_DIFX = FCL_X;

    }

    // Decision
    if (FCL_Y < 0)
    {    

      // Calculation
      FCL_DIFY = -FCL_Y;

    } else {

      // Calculation
      FCL_DIFY = FCL_Y;

    }

    // Decision
    if (FCL_Z < 0)
    {    

      // Calculation
      FCL_DIFZ = -FCL_Z;

    } else {

      // Calculation
      FCL_DIFZ = FCL_Z;

    }

    // Decision
    if ((FCL_DIFX > FCL_DIFY) && (FCL_DIFX > FCL_DIFZ))
    {    

      // Decision
      if (FCL_X < 0)
      {      

        // Call Component Macro
        FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 16, "Left    ", 9, 0);

        // Decision
        if ((FCV_COUNT & 0x10) == 0)
        {        

          // Call Macro
          FCM_Beep();

        // } else {

        }

        // Calculation
        FCV_COUNT = FCV_COUNT | 0x10;

      } else {

        // Call Component Macro
        FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 16, "Right   ", 9, 0);

        // Decision
        if ((FCV_COUNT & 0x20) == 0)
        {        

          // Call Macro
          FCM_Beep();

        // } else {

        }

        // Calculation
        FCV_COUNT = FCV_COUNT | 0x20;

      }

    } else {

      // Decision
      if ((FCL_DIFY > FCL_DIFX) && (FCL_DIFY > FCL_DIFZ))
      {      

        // Decision
        if (FCL_Y < 0)
        {        

          // Call Component Macro
          FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 16, "Front    ", 10, 0);

          // Decision
          if ((FCV_COUNT & 0x04) == 0)
          {          

            // Call Macro
            FCM_Beep();

          // } else {

          }

          // Calculation
          FCV_COUNT = FCV_COUNT | 0x04;

        } else {

          // Call Component Macro
          FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 16, "Back    ", 9, 0);

          // Decision
          if ((FCV_COUNT & 0x08) == 0)
          {          

            // Call Macro
            FCM_Beep();

          // } else {

          }

          // Calculation
          FCV_COUNT = FCV_COUNT | 0x08;

        }

      } else {

        // Decision
        if ((FCL_DIFZ > FCL_DIFY) && (FCL_DIFZ > FCL_DIFX))
        {        

          // Decision
          if (FCL_Z < 0)
          {          

            // Call Component Macro
            FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 16, "Flat    ", 9, 0);

            // Decision
            if ((FCV_COUNT & 0x02) == 0)
            {            

              // Call Macro
              FCM_Beep();

            // } else {

            }

            // Calculation
            FCV_COUNT = FCV_COUNT | 0x02;

          } else {

            // Call Component Macro
            FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 16, "Inverted ", 10, 0);

            // Decision
            if ((FCV_COUNT & 0x01) == 0)
            {            

              // Call Macro
              FCM_Beep();

            // } else {

            }

            // Calculation
            FCV_COUNT = FCV_COUNT | 0x01;

          }

        // } else {

        }

      }

    }

    // Delay
    FCI_DELAYBYTE_MS(100);

    // Read Switch Pins
    FCV_IDX = GET_PORT_MASK(A,0x0003);

    // Decision
    if (FCV_IDX > 0)
    {    

      // Calculation
      FCV_DONE = 1;

    // } else {

    }

    // Decision
    if (FCV_COUNT == 0x3F)
    {    

      // Calculation
      FCV_PASSCOUNT = FCV_PASSCOUNT | 0x40;
      FCV_IDX = 2;

      // Calculation
      FCV_DONE = 1;

    // } else {

    }

  }

}

/*=----------------------------------------------------------------------=*\
   Use :Parameters for macro Read_2_Byte_Packet:
       :  idx : MX_UINT8
       :
       :Returns : MX_UINT16
\*=----------------------------------------------------------------------=*/
MX_UINT16 FCM_Read_2_Byte_Packet(MX_UINT8 FCL_IDX)
{
  //Local variable definitions
  MX_UINT8 FCL_DAT0;
  MX_UINT8 FCL_DAT1;
  MX_UINT16 FCR_RETVAL;


  // Read Byte From Buffer
  FCL_DAT0 = FCD_07fa1_FAT1__ReadByteFromBuffer(FCL_IDX);

  // Read Byte From Buffer
  FCL_DAT1 = FCD_07fa1_FAT1__ReadByteFromBuffer(FCL_IDX + 1);

  // Position bytes into long variable
  FCR_RETVAL = 0;
  FCR_RETVAL = FCR_RETVAL | FCL_DAT1;
  FCR_RETVAL = FCR_RETVAL << 8;
  FCR_RETVAL = FCR_RETVAL | FCL_DAT0;

  return (FCR_RETVAL);

}

