/*=----------------------------------------------------------------------=*\
   Use :Returns : MX_UINT16
\*=----------------------------------------------------------------------=*/
MX_UINT16 FCM_ReadMic()
{
  //Local variable definitions
  MX_UINT16 FCL_MIN;
  MX_UINT16 FCL_MAX;
  MX_UINT16 FCL_DATA;
  MX_UINT16 FCR_RETVAL;


  // Calculation
  FCL_MIN = 65535;
  FCL_MAX = 0;

  // Collect data for 20ms
  for (FCLV_LOOP1=0; (FCLV_LOOP1)<(200); (FCLV_LOOP1)++)
  {
    // Call Component Macro
    FCL_DATA = FCD_0dcd1_FormulaAllcode1__ReadMic();

    // Decision
    if (FCL_DATA > FCL_MAX)
    {    

      // Calculation
      FCL_MAX = FCL_DATA;

    // } else {

    }

    // Decision
    if (FCL_DATA < FCL_MIN)
    {    

      // Calculation
      FCL_MIN = FCL_DATA;

    // } else {

    }

    // Delay
    FCI_DELAYBYTE_US(100);

  }

  // Calculation
  FCR_RETVAL = FCL_MAX - FCL_MIN;

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Parameters for macro RecordAudio:
       :  Filename[12] : MX_CHAR (by-ref)
       :  BitDepth : 0=8-bit, 1=16-bit
       :  SampleRate : 0=8KHz, 1=16KHz
       :  RecordTime : Time to record in seconds
       :
       :Returns : MX_UINT8
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_RecordAudio(MX_CHAR *FCL_FILENAME, MX_UINT16 FCLsz_FILENAME, MX_UINT8 FCL_BITDEPTH, MX_UINT8 FCL_SAMPLERATE, MX_UINT16 FCL_RECORDTIME)
{
  //Local variable definitions
  MX_UINT8 FCL_RETVAL;
  MX_UINT32 FCL_CHUNKSIZECALC;
  MX_UINT16 FCL_IDX;
  MX_SINT16 FCL_DATA;
  MX_UINT32 FCL_SAMPRATENUM;
  MX_UINT8 FCR_RETVAL;


  // Call Component Macro
  FCL_RETVAL = FCD_07fa1_FAT1__CreateFile(FCL_FILENAME, FCLsz_FILENAME);

  // Decision
  if (FCL_RETVAL == 0)
  {  

    // Call Component Macro
    FCL_RETVAL = FCD_07fa1_FAT1__OpenFile(FCL_FILENAME, FCLsz_FILENAME);

    // Decision
    if (FCL_RETVAL == 0)
    {    

      // Decision
      if (FCL_SAMPLERATE == 0)
      {      

        // Calculation
        FCL_SAMPRATENUM = 8000;

      } else {

        // Calculation
        FCL_SAMPRATENUM = 16000;

      }

      // Calculation
      FCL_CHUNKSIZECALC = (FCL_SAMPRATENUM * FCL_RECORDTIME);
      FCL_CHUNKSIZECALC = FCL_CHUNKSIZECALC * (FCL_BITDEPTH + 1);

      // Calculation
      FCL_CHUNKSIZECALC = FCL_CHUNKSIZECALC + 36;

      // ChunkID
      FCD_07fa1_FAT1__WriteByteToBuffer(0, 'R');

      // ChunkID
      FCD_07fa1_FAT1__WriteByteToBuffer(1, 'I');

      // ChunkID
      FCD_07fa1_FAT1__WriteByteToBuffer(2, 'F');

      // ChunkID
      FCD_07fa1_FAT1__WriteByteToBuffer(3, 'F');

      // Chunk Size
      FCD_07fa1_FAT1__WriteByteToBuffer(4, FCL_CHUNKSIZECALC & 0xFF);

      // Chunk Size
      FCD_07fa1_FAT1__WriteByteToBuffer(5, FCL_CHUNKSIZECALC >> 8);

      // Chunk Size
      FCD_07fa1_FAT1__WriteByteToBuffer(6, FCL_CHUNKSIZECALC / 65536);

      // Chunk Size
      FCD_07fa1_FAT1__WriteByteToBuffer(7, FCL_CHUNKSIZECALC / 16777216);

      // Format
      FCD_07fa1_FAT1__WriteByteToBuffer(8, 'W');

      // Format
      FCD_07fa1_FAT1__WriteByteToBuffer(9, 'A');

      // Format
      FCD_07fa1_FAT1__WriteByteToBuffer(10, 'V');

      // Format
      FCD_07fa1_FAT1__WriteByteToBuffer(11, 'E');

      // SubChunk1ID
      FCD_07fa1_FAT1__WriteByteToBuffer(12, 'f');

      // SubChunk1ID
      FCD_07fa1_FAT1__WriteByteToBuffer(13, 'm');

      // SubChunk1ID
      FCD_07fa1_FAT1__WriteByteToBuffer(14, 't');

      // SubChunk1ID
      FCD_07fa1_FAT1__WriteByteToBuffer(15, ' ');

      // SubChunk1Size
      FCD_07fa1_FAT1__WriteByteToBuffer(16, 16);

      // SubChunk1Size
      FCD_07fa1_FAT1__WriteByteToBuffer(17, 0);

      // SubChunk1Size
      FCD_07fa1_FAT1__WriteByteToBuffer(18, 0);

      // SubChunk1Size
      FCD_07fa1_FAT1__WriteByteToBuffer(19, 0);

      // Audio Format - PCM
      FCD_07fa1_FAT1__WriteByteToBuffer(20, 1);

      // Audio Format - PCM
      FCD_07fa1_FAT1__WriteByteToBuffer(21, 0);

      // MONO
      FCD_07fa1_FAT1__WriteByteToBuffer(22, 1);

      // MONO
      FCD_07fa1_FAT1__WriteByteToBuffer(23, 0);

      // Sample Rate
      FCD_07fa1_FAT1__WriteByteToBuffer(24, FCL_SAMPRATENUM & 0xFF);

      // Sample Rate
      FCD_07fa1_FAT1__WriteByteToBuffer(25, FCL_SAMPRATENUM >> 8);

      // Sample Rate
      FCD_07fa1_FAT1__WriteByteToBuffer(26, 0);

      // Sample Rate
      FCD_07fa1_FAT1__WriteByteToBuffer(27, 0);

      // Decision
      if (FCL_BITDEPTH == 0)
      {      

        // Byte Rate
        FCD_07fa1_FAT1__WriteByteToBuffer(28, FCL_SAMPRATENUM & 0xFF);

        // Byte Rate
        FCD_07fa1_FAT1__WriteByteToBuffer(29, FCL_SAMPRATENUM >> 8);

        // Byte Rate
        FCD_07fa1_FAT1__WriteByteToBuffer(30, 0);

        // Byte Rate
        FCD_07fa1_FAT1__WriteByteToBuffer(31, 0);

        // Block Align
        FCD_07fa1_FAT1__WriteByteToBuffer(32, 1);

        // Block Align
        FCD_07fa1_FAT1__WriteByteToBuffer(33, 0);

        // Bits Per Sample
        FCD_07fa1_FAT1__WriteByteToBuffer(34, 8);

        // Bits Per Sample
        FCD_07fa1_FAT1__WriteByteToBuffer(35, 0);

      } else {

        // Byte Rate
        FCD_07fa1_FAT1__WriteByteToBuffer(28, (FCL_SAMPRATENUM << 1) & 0xFF);

        // Byte Rate
        FCD_07fa1_FAT1__WriteByteToBuffer(29, FCL_SAMPRATENUM >> 7);

        // Byte Rate
        FCD_07fa1_FAT1__WriteByteToBuffer(30, 0);

        // Byte Rate
        FCD_07fa1_FAT1__WriteByteToBuffer(31, 0);

        // Block Align
        FCD_07fa1_FAT1__WriteByteToBuffer(32, 2);

        // Block Align
        FCD_07fa1_FAT1__WriteByteToBuffer(33, 0);

        // Bits Per Sample
        FCD_07fa1_FAT1__WriteByteToBuffer(34, 16);

        // Bits Per Sample
        FCD_07fa1_FAT1__WriteByteToBuffer(35, 0);

      }

      // SubChunk2ID
      FCD_07fa1_FAT1__WriteByteToBuffer(36, 'd');

      // SubChunk2ID
      FCD_07fa1_FAT1__WriteByteToBuffer(37, 'a');

      // SubChunk2ID
      FCD_07fa1_FAT1__WriteByteToBuffer(38, 't');

      // SubChunk2ID
      FCD_07fa1_FAT1__WriteByteToBuffer(39, 'a');

      // Calculation
      FCL_CHUNKSIZECALC = FCL_CHUNKSIZECALC - 36;

      // SubChunk2Size
      FCD_07fa1_FAT1__WriteByteToBuffer(40, FCL_CHUNKSIZECALC & 0xFF);

      // SubChunk2Size
      FCD_07fa1_FAT1__WriteByteToBuffer(41, FCL_CHUNKSIZECALC >> 8);

      // SubChunk2Size
      FCD_07fa1_FAT1__WriteByteToBuffer(42, FCL_CHUNKSIZECALC / 65536);

      // SubChunk2Size
      FCD_07fa1_FAT1__WriteByteToBuffer(43, FCL_CHUNKSIZECALC / 16777216);

      // Calculation
      FCL_CHUNKSIZECALC = (FCL_SAMPRATENUM * FCL_RECORDTIME);

      // Calculation
      FCL_IDX = 44;

      // Call Component Macro
      FCL_DATA = FCD_0dcd1_FormulaAllcode1__AudioQueueLength();

      // Ensure Buffer Is Empty
      while (FCL_DATA > 0)
      {
        // Call Component Macro
        FCL_DATA = FCD_0dcd1_FormulaAllcode1__AudioReadFromBuffer();

        // Call Component Macro
        FCL_DATA = FCD_0dcd1_FormulaAllcode1__AudioQueueLength();

      }

      // Call Component Macro
      FCD_0dcd1_FormulaAllcode1__AudioStreamControl(((FCL_BITDEPTH + 1) * 8) + 1, FCL_SAMPLERATE);

      // Loop
      while (FCL_CHUNKSIZECALC > 0)
      {
        // Call Component Macro
        FCL_DATA = FCD_0dcd1_FormulaAllcode1__AudioQueueLength();

        // Decision
        if (FCL_DATA > 0)
        {        

          // Call Component Macro
          FCL_DATA = FCD_0dcd1_FormulaAllcode1__AudioReadFromBuffer();

          // Decision
          if (FCL_BITDEPTH == 0)
          {          

            // Data
            FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX, FCL_DATA);

          } else {

            // Data
            FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX, FCL_DATA & 0xFF);

            // Calculation
            FCL_IDX = FCL_IDX + 1;

            // Data
            FCD_07fa1_FAT1__WriteByteToBuffer(FCL_IDX, FCL_DATA >> 8);

          }

          // Calculation
          FCL_IDX = FCL_IDX + 1;

          // Decision
          if (FCL_IDX == 512)
          {          

            // Calculation
            FCL_IDX = 0;

            // Call Component Macro
            FCD_07fa1_FAT1__WriteFileSector();

            // Call Component Macro
            FCD_07fa1_FAT1__MoveToNextFileSector(1);

          // } else {

          }

          // Calculation
          FCL_CHUNKSIZECALC = FCL_CHUNKSIZECALC - 1;

        // } else {

        }

      }

      // Call Component Macro
      FCD_0dcd1_FormulaAllcode1__AudioStreamControl(0, FCL_SAMPLERATE);

      // If there is data in a new sector
      if (FCL_IDX > 0)
      {      

        // Ensure sector gets written
        FCD_07fa1_FAT1__WriteFileSector();

      // } else {

      }

      // Call Component Macro
      FCL_DATA = FCD_0dcd1_FormulaAllcode1__AudioQueueLength();

      // Ensure Buffer Is Empty
      while (FCL_DATA > 0)
      {
        // Call Component Macro
        FCL_DATA = FCD_0dcd1_FormulaAllcode1__AudioReadFromBuffer();

        // Call Component Macro
        FCL_DATA = FCD_0dcd1_FormulaAllcode1__AudioQueueLength();

      }

      // Calculation
      FCR_RETVAL = 0;

    } else {

      // Calculation
      FCR_RETVAL = 255;

    }

  } else {

    // Decision
    if (FCL_RETVAL == 1)
    {    

      // Calculation
      FCR_RETVAL = 1;

    } else {

      // Calculation
      FCR_RETVAL = 255;

    }

  }

  return (FCR_RETVAL);

}

