/*=----------------------------------------------------------------------=*\
   Use :
\*=----------------------------------------------------------------------=*/
void FCM_WaitForClap()
{
  //Local variable definitions
  #define FCLsz_SAMPLES 2
  MX_UINT16 FCL_SAMPLES[FCLsz_SAMPLES];


  // Calculation
  FCV_DONE = 0;

  // Calculation
  FCL_SAMPLES[1] = 4095;

  // Call Component Macro
  FCD_0dcd1_FormulaAllcode1__LCDClear();

  // Call Component Macro
  FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 0, "Clap Test", 10, 0);

  // Loop
  while (FCV_DONE == 0)
  {
    // Call Component Macro
    FCL_SAMPLES[0] = FCD_0dcd1_FormulaAllcode1__ReadMic();

    // Delay
    FCI_DELAYBYTE_MS(1);

    // Read Switch Pins
    FCV_IDX = GET_PORT_MASK(A,0x0003);

    // Decision
    if (FCV_IDX > 0)
    {    

      // Calculation
      FCV_DONE = 1;

    // } else {

    }

    // Decision
    if (FCL_SAMPLES[0] > (FCL_SAMPLES[1] + 500))
    {    

      // Call Macro
      FCM_Beep();

      // Calculation
      FCV_DONE = 1;

      // Calculation
      FCV_IDX = 2;

      // Calculation
      FCV_PASSCOUNT = FCV_PASSCOUNT | 0x20;

    // } else {

    }

    // Calculation
    FCL_SAMPLES[1] = FCL_SAMPLES[0];

  }

  //Local variable definitions
  #undef FCLsz_SAMPLES
}

