/*=----------------------------------------------------------------------=*\
   Use :
\*=----------------------------------------------------------------------=*/
void FCM_Tones()
{
  //Local variable definitions
  MX_UINT16 FCL_DELAY = (0xbb8);


  // 
  while (FCL_DELAY > 200)
  {
    // Output
    SET_PORT_PIN(F,3,(1));

    // Delay
    FCI_DELAYINT_US(FCL_DELAY);

    // Output
    SET_PORT_PIN(F,3,(0));

    // Delay
    FCI_DELAYINT_US(FCL_DELAY);

    // Calculation
    FCL_DELAY = FCL_DELAY - 30;

  }

}

