/*=----------------------------------------------------------------------=*\
   Use :
\*=----------------------------------------------------------------------=*/
void FCM_Beep()
{
  //Local variable definitions
  MX_UINT16 FCL_DELAY = (0xbb8);


  // Calculation
  FCL_DELAY = 100;

  // 
  for (FCLV_LOOP2=0; (FCLV_LOOP2)<(100); (FCLV_LOOP2)++)
  {
    // Output
    SET_PORT_PIN(F,3,(1));

    // Delay
    FCI_DELAYINT_US(FCL_DELAY);

    // Output
    SET_PORT_PIN(F,3,(0));

    // Delay
    FCI_DELAYINT_US(FCL_DELAY);

  }

}

