/*=----------------------------------------------------------------------=*\
   Use :Parameters for macro PlaybackAudio:
       :  Filename[12] : MX_CHAR
       :
       :Returns : MX_UINT8
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_PlaybackAudio(MX_CHAR *PFCL_FILENAME)
{
  //Local variable definitions
  MX_UINT8 FCL_EOF = (0x0);
  MX_UINT16 FCL_SAMPLERATE;
  MX_UINT8 FCL_BITDEPTH;
  MX_UINT8 FCL_NUMCHANS;
  MX_UINT8 FCL_RETVAL;
  MX_UINT16 FCL_DATA;
  MX_UINT16 FCL_ZCOUNT = (0x0);
  MX_UINT16 FCL_AUDIOQLEN;
  MX_UINT8 FCR_RETVAL;

  #define FCLsz_FILENAME 12
  MX_CHAR FCL_FILENAME[FCLsz_FILENAME];
  FCI_CONCATENATE(PFCL_FILENAME,FCLsz_FILENAME,"",0,FCL_FILENAME,FCLsz_FILENAME);


  // Calculation
  FCR_RETVAL = 255;
  FCL_DATA = 0;

  // Call Component Macro
  FCL_RETVAL = FCD_07fa1_FAT1__OpenFile(FCL_FILENAME, FCLsz_FILENAME);

  // File found and open?
  if (FCL_RETVAL == 0)
  {  

    // Read Start of file - should be "RIFF"
    FCL_RETVAL = FCD_07fa1_FAT1__ReadByteFromBuffer(0);

    // Decision
    if (FCL_RETVAL == 'R')
    {    

      // Read Start of file - should be "RIFF"
      FCL_RETVAL = FCD_07fa1_FAT1__ReadByteFromBuffer(1);

      // Decision
      if (FCL_RETVAL == 'I')
      {      

        // Read Start of file - should be "RIFF"
        FCL_RETVAL = FCD_07fa1_FAT1__ReadByteFromBuffer(2);

        // Decision
        if (FCL_RETVAL == 'F')
        {        

          // Read Start of file - should be "RIFF"
          FCL_RETVAL = FCD_07fa1_FAT1__ReadByteFromBuffer(3);

          // Decision
          if (FCL_RETVAL == 'F')
          {          

            // Read Number Of Channels: Mono = 1, Stereo = 2
            FCL_NUMCHANS = FCD_07fa1_FAT1__ReadByteFromBuffer(22);

            // Read Sample Rate LSB
            FCL_SAMPLERATE = FCD_07fa1_FAT1__ReadByteFromBuffer(24);

            // Read Sample Rate MSB
            FCL_RETVAL = FCD_07fa1_FAT1__ReadByteFromBuffer(25);

            // Combine Sample Rate Bytes
            FCL_SAMPLERATE = FCL_SAMPLERATE + (FCL_RETVAL << 8);

            // Decision
            if (FCL_SAMPLERATE == 8000)
            {            

              // Combine Sample Rate Bytes
              FCL_SAMPLERATE = 0;

            } else {

              // Decision
              if (FCL_SAMPLERATE == 16000)
              {              

                // Combine Sample Rate Bytes
                FCL_SAMPLERATE = 1;

              } else {

                // Goto Connection Point
                goto FCC_PlaybackAudio_A;

              }

            }

            // Read Bits Per Sample
            FCL_BITDEPTH = FCD_07fa1_FAT1__ReadByteFromBuffer(34);

            // Call Component Macro
            FCD_0dcd1_FormulaAllcode1__AudioStreamControl(FCL_BITDEPTH, FCL_SAMPLERATE);

            // Loop
            while (FCL_EOF == 0)
            {
              // Switch
              switch (FCL_BITDEPTH)
              {
                case 8:
                {

                  // Call Component Macro
                  FCL_DATA = FCD_07fa1_FAT1__ReadByteFromFile();

                  break;
                }
                case 16:
                {

                  // Call Component Macro
                  FCL_DATA = FCD_07fa1_FAT1__ReadByteFromFile();

                  // Call Component Macro
                  FCL_RETVAL = FCD_07fa1_FAT1__ReadByteFromFile();

                  // Combine data readings
                  FCL_DATA = FCL_DATA + (FCL_RETVAL << 8);

                  break;
                }
                // default:

              }

              // Decision
              if (FCL_NUMCHANS == 2)
              {              

                // Switch
                switch (FCL_BITDEPTH)
                {
                  case 8:
                  {

                    // Skip over alt stero channel
                    FCL_RETVAL = FCD_07fa1_FAT1__ReadByteFromFile();

                    break;
                  }
                  case 16:
                  {

                    // Skip Over Alt Stereo Channel
                    FCL_RETVAL = FCD_07fa1_FAT1__ReadByteFromFile();

                    // Skip Over Alt Stereo Channel
                    FCL_RETVAL = FCD_07fa1_FAT1__ReadByteFromFile();

                    break;
                  }
                  // default:

                }

              // } else {

              }

              // Call Component Macro
              FCD_0dcd1_FormulaAllcode1__AudioAddToBuffer(FCL_DATA);

              // Call Component Macro
              FCL_AUDIOQLEN = FCD_0dcd1_FormulaAllcode1__AudioQueueLength();

              // Don't overfill buffer, wait for count to drop below 2000 samples
              while (FCL_AUDIOQLEN > 2000)
              {
                // Call Component Macro
                FCL_AUDIOQLEN = FCD_0dcd1_FormulaAllcode1__AudioQueueLength();

              }

              // Decision
              if (FCL_DATA == 0)
              {              

                // Calculation
                FCL_ZCOUNT = FCL_ZCOUNT + 1;

                // Decision
                if (FCL_ZCOUNT == 1000)
                {                

                  // Calculation
                  FCL_EOF = 1;

                // } else {

                }

              } else {

                // Calculation
                FCL_ZCOUNT = 0;

              }

            }

            // Call Component Macro
            FCD_0dcd1_FormulaAllcode1__AudioStreamControl(0, FCL_SAMPLERATE);

            // Calculation
            FCR_RETVAL = 0;

            // Connection Point
          FCC_PlaybackAudio_A:
            ;

          // } else {

          }

        // } else {

        }

      // } else {

      }

    // } else {

    }

  } else {

    // Calculation
    FCR_RETVAL = 239;

  }

  return (FCR_RETVAL);

  //Local variable definitions
  #undef FCLsz_FILENAME
}

/*=----------------------------------------------------------------------=*\
   Use :Parameters for macro HuntForCommandAndParams:
       :  Command[20] : MX_CHAR (by-ref)
       :  ParamCount : MX_UINT8
       :  ParamMask : MX_UINT8
       :  comp : MX_UINT8
       :  macro : MX_UINT8
       :
       :Returns : MX_UINT8
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_HuntForCommandAndParams(MX_CHAR *FCL_COMMAND, MX_UINT16 FCLsz_COMMAND, MX_UINT8 FCL_PARAMCOUNT, MX_UINT8 FCL_PARAMMASK, MX_UINT8 FCL_COMP, MX_UINT8 FCL_MACRO)
{
  //Local variable definitions
  MX_UINT8 FCL_FOUND;
  MX_UINT8 FCL_IDX = (0x0);
  MX_UINT16 FCL_PARAM;
  MX_UINT8 FCL_COUNT = (0x0);
  MX_UINT8 FCL_LEN;
  MX_UINT8 FCR_RETVAL;


  // Calculation
  FCL_LEN = FCI_GETLENGTH(FCL_COMMAND, FCLsz_COMMAND);

  // Call Component Macro
  FCL_FOUND = FCD_01211_CommandBuffer__LookForValue(FCL_COMMAND, FCLsz_COMMAND, FCL_LEN, 0, 1);

  // Decision
  if (FCL_FOUND)
  {  

    // Decision
    if (FCV_LCDVERBOSE == 1)
    {    

      // Call Component Macro
      FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 0, FCL_COMMAND, FCLsz_COMMAND, 0);

    // } else {

    }

    // Search Again but this time get rid of command data
    FCL_FOUND = FCD_01211_CommandBuffer__LookForValue(FCL_COMMAND, FCLsz_COMMAND, FCL_LEN, 1, 1);

    // Calculation
    FCV_COMPONENT = FCL_COMP;
    FCV_MACROIDX = FCL_MACRO;

    // Call Macro
    FCM_GetRequiredCount();

    // Loop
    while (FCL_IDX < FCL_PARAMCOUNT)
    {
      // Decision
      if ((FCL_PARAMCOUNT == 255) && (FCL_COUNT >= FCV_STRINGOFFSET))
      {      

        // Call Component Macro
        FCL_FOUND = FCD_01211_CommandBuffer__GetNumberBytes();

        // Decision
        if (FCL_FOUND == 0)
        {        

          // Calculation
          FCV_PARAMCOUNTER = FCL_COUNT;
          FCL_IDX = 254;

        } else {

          // Call Component Macro
          FCL_FOUND = FCD_01211_CommandBuffer__GetByte();

          // Calculation
          FCV_PARAMETERS[FCL_COUNT] = FCL_FOUND;

          // Calculation
          FCL_COUNT = FCL_COUNT + 1;

        }

      } else {

        // Call Macro
        FCL_PARAM = FCM_GetStringParam();

        // Decision
        if (FCV_LCDVERBOSE == 1)
        {        

          // Decision
          if (FCL_IDX < 6)
          {          

            // Call Component Macro
            FCD_0dcd1_FormulaAllcode1__LCDPrintNumber(FCL_IDX * 16, 8, FCL_PARAM, 0);

          // } else {

          }

        // } else {

        }

        // Decision
        if (FCL_PARAMMASK & (0x01 << FCL_IDX))
        {        

          // Calculation
          FCV_PARAMETERS[FCL_COUNT] = (FCL_PARAM & 0xFF);

          // Calculation
          FCL_COUNT = FCL_COUNT + 1;

          // Calculation
          FCV_PARAMETERS[FCL_COUNT] = (FCL_PARAM >> 8);

          // Calculation
          FCL_COUNT = FCL_COUNT + 1;

        } else {

          // Calculation
          FCV_PARAMETERS[FCL_COUNT] = (FCL_PARAM & 0xFF);

          // Calculation
          FCL_COUNT = FCL_COUNT + 1;

        }

      }

      // Calculation
      FCL_IDX = FCL_IDX + 1;

    }

    // Calculation
    FCR_RETVAL = 1;

  } else {

    // Calculation
    FCR_RETVAL = 0;

  }

  return (FCR_RETVAL);

}

