/*=----------------------------------------------------------------------=*\
   Use :
\*=----------------------------------------------------------------------=*/
void FCM_MotorIR()
{
  //Local variable definitions
  MX_UINT16 FCL_LEFT;
  MX_UINT16 FCL_RIGHT;
  MX_UINT8 FCL_BEEPED = (0x0);
  MX_UINT8 FCL_COUNT = (0x0);


  // Call Component Macro
  FCD_0dcd1_FormulaAllcode1__LCDClear();

  // Call Component Macro
  FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 0, "Motor Balance", 14, 0);

  // Loop
  while (FCV_IDX == 0)
  {
    // Read Switch Pins
    FCV_IDX = GET_PORT_MASK(A,0x0003);

  }

  // Decision
  if (FCV_IDX == 2)
  {  

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 8, "Started", 8, 0);

    // Delay
    FCI_DELAYBYTE_S(1);

    // Call Macro
    FCD_0dcd1_FormulaAllcode1__SetMotors(40, 40);

    // Loop
    for (FCLV_LOOP3=0; (FCLV_LOOP3)<(80); (FCLV_LOOP3)++)
    {
      // Loop
      for (FCLV_LOOP4=0; (FCLV_LOOP4)<(250); (FCLV_LOOP4)++)
      {
        // Call Component Macro
        FCL_LEFT = FCD_0dcd1_FormulaAllcode1__ReadLineSensor(0);

        // Call Component Macro
        FCL_RIGHT = FCD_0dcd1_FormulaAllcode1__ReadLineSensor(1);

        // Delay
        FCI_DELAYBYTE_US(20);

        // Decision
        if ((FCL_LEFT < 22))
        {        

          // Decision
          if ((FCL_RIGHT < 22))
          {          

            // Decision
            if (FCL_BEEPED == 0)
            {            

              // Call Macro
              FCM_Beep();

              // Goto Connection Point
              goto FCC_MotorIR_A;

              // Calculation
              FCL_COUNT = FCL_COUNT + 1;
              FCL_BEEPED = 1;

            // } else {

            }

          } else {

            // Calculation
            FCL_BEEPED = 0;

          }

        } else {

          // Calculation
          FCL_BEEPED = 0;

        }

      }

      // Connection Point
    FCC_MotorIR_A:
      ;

    }

    // Call Macro
    FCD_0dcd1_FormulaAllcode1__SetMotors(0, 0);

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDClear();

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 0, "Done", 5, 0);

  // } else {

  }

}

