/*=----------------------------------------------------------------------=*\
   Use :
\*=----------------------------------------------------------------------=*/
void FCM_Menu()
{
  //Local variable definitions
  MX_UINT8 FCL_SWSTATE;
  #define FCLsz_TEMPSTR 20
  MX_CHAR FCL_TEMPSTR[FCLsz_TEMPSTR];
  MX_UINT8 FCL_RX = (0x1);
  MX_UINT8 FCL_COUNT = (0x0);
  MX_UINT8 FCL_STRLEN;


  // Call Component Macro
  FCL_SWSTATE = FCD_0dcd1_FormulaAllcode1__BluetoothCheckConnection();

  // Decision
  if (FCL_SWSTATE == 0)
  {  

    // Calculation
    FCL_COUNT = 0;

    // Output
    SET_PORT_PIN(F,13,(0));

    // Delay
    FCI_DELAYBYTE_MS(1);

    // Output
    SET_PORT_PIN(F,13,(1));

    // Delay
    FCI_DELAYBYTE_MS(5);

    // Delay
    FCI_DELAYINT_MS(400);

    // Call Component Macro
    FCL_SWSTATE = FCD_0dcd1_FormulaAllcode1__BluetoothQueueLength();

    // Loop
    while (FCL_SWSTATE > 0)
    {
      // Call Component Macro
      FCL_RX = FCD_0dcd1_FormulaAllcode1__BluetoothReceive();

      // Call Component Macro
      FCL_SWSTATE = FCD_0dcd1_FormulaAllcode1__BluetoothQueueLength();

    }

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__BluetoothTransmitString("AT+NAME\r\n", 10);

    // Delay
    FCI_DELAYBYTE_MS(5);

    // Call Component Macro
    FCL_SWSTATE = FCD_0dcd1_FormulaAllcode1__BluetoothQueueLength();

    // Calculation
    FCL_COUNT = 0;

    // Loop
    while (FCL_SWSTATE > 0)
    {
      // Call Component Macro
      FCL_RX = FCD_0dcd1_FormulaAllcode1__BluetoothReceive();

      // Decision
      if (FCL_COUNT > 5)
      {      

        // Calculation
        FCL_TEMPSTR[FCL_COUNT - 6] = FCL_RX;

      // } else {

      }

      // Calculation
      FCL_COUNT = FCL_COUNT + 1;

      // Delay
      FCI_DELAYBYTE_US(50);

      // Call Component Macro
      FCL_SWSTATE = FCD_0dcd1_FormulaAllcode1__BluetoothQueueLength();

    }

    // Decision
    if (FCL_COUNT)
    {    

      // Calculation
      FCL_TEMPSTR[FCL_COUNT - 6] = 0;
      FCL_STRLEN = FCI_GETLENGTH(FCL_TEMPSTR, FCLsz_TEMPSTR);
      FCI_LEFTSTRING(FCL_TEMPSTR, FCLsz_TEMPSTR, FCL_STRLEN - 2, FCL_TEMPSTR,20);

    } else {

      // Calculation
      FCI_SCOPY("BT_ERR",7, FCL_TEMPSTR,FCLsz_TEMPSTR);

    }

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 0, FCL_TEMPSTR, FCLsz_TEMPSTR, 0);

  } else {

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 0, "Paired", 7, 0);

  }

  // Default To API mode
  FCV_MODE = 2;

  // Calculation
  FCV_DONE = 0;

  // Calculation
  {
  MX_CHAR FCI_TMP_STR[MX_MAX_TMPSTR_SIZE];
  FCI_SHEAD("v",2, FCI_TOSTRING(6, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE),20, FCL_TEMPSTR,20);
  FCL_STRLEN = FCI_GETLENGTH(FCL_TEMPSTR, FCLsz_TEMPSTR);
  FCL_RX = 127 - (FCL_STRLEN * 6);
  }

  // Print Version Number
  FCD_0dcd1_FormulaAllcode1__LCDPrintString(FCL_RX, 0, FCL_TEMPSTR, FCLsz_TEMPSTR, 0);

  // Call Component Macro
  FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 24, "SW1 = Mode   SW2 = Go", 22, 0);

  // Call Component Macro
  FCD_0dcd1_FormulaAllcode1__LCDPrintString(30, 12, "Mode = API", 11, 0);

  // Loop
  while (FCV_DONE == 0)
  {
    // Call Component Macro
    FCL_SWSTATE = FCD_0dcd1_FormulaAllcode1__ReadSwitch(1);

    // Decision
    if (FCL_SWSTATE)
    {    

      // Calculation
      FCV_MODE = FCV_MODE + 1;

      // Decision
      if (FCV_MODE > 2)
      {      

        // Calculation
        FCV_MODE = 0;

      // } else {

      }

      // Switch
      switch (FCV_MODE)
      {
        case 1:
        {

          // Call Component Macro
          FCD_0dcd1_FormulaAllcode1__LCDPrintString(70, 12, "Test", 5, 0);

          break;
        }
        case 2:
        {

          // Call Component Macro
          FCD_0dcd1_FormulaAllcode1__LCDPrintString(70, 12, "API ", 5, 0);

          break;
        }
        default:
        {
          // Call Component Macro
          FCD_0dcd1_FormulaAllcode1__LCDPrintString(70, 12, "Demo", 5, 0);

        }
      }

      // Delay
      FCI_DELAYBYTE_MS(250);

    // } else {

    }

    // Call Component Macro
    FCL_SWSTATE = FCD_0dcd1_FormulaAllcode1__ReadSwitch(0);

    // Decision
    if (FCL_SWSTATE)
    {    

      // Calculation
      FCV_DONE = 1;

    // } else {

    }

    //Comment:
    //Bail out if we are in the menu and 
    //API commands start being received

    // Call Component Macro
    FCL_SWSTATE = FCD_0dcd1_FormulaAllcode1__BluetoothCheckConnection();

    // Decision
    if (FCL_SWSTATE)
    {    

      // Call Component Macro
      FCL_SWSTATE = FCD_0dcd1_FormulaAllcode1__BluetoothQueueLength();

      // Decision
      if (FCL_SWSTATE)
      {      

        // Calculation
        FCV_DONE = 1;
        FCV_MODE = 2;

      // } else {

      }

    // } else {

    }

  }

  // Call Component Macro
  FCD_0dcd1_FormulaAllcode1__LCDPrintString(0, 24, "                     ", 22, 0);

  //Local variable definitions
  #undef FCLsz_TEMPSTR
}

/*=----------------------------------------------------------------------=*\
   Use :
\*=----------------------------------------------------------------------=*/
void FCM_LineFollow()
{
  //Local variable definitions
  MX_UINT16 FCL_THRESH = (0xf0a);
  MX_UINT8 FCL_SW;


  // Delay
  FCI_DELAYBYTE_S(1);

  // Calculation
  FCV_DONE = 0;
  FCV_COUNT = 0;

  // Loop
  while (FCV_DONE == 0)
  {
    // Call Macro
    FCV_LEFT = FCD_0dcd1_FormulaAllcode1__ReadLineSensor(0);

    // Call Macro
    FCV_RIGHT = FCD_0dcd1_FormulaAllcode1__ReadLineSensor(1);

    // Decision
    if (FCV_RIGHT > FCL_THRESH)
    {    

      // Decision
      if (FCV_LEFT < FCL_THRESH)
      {      

        // Calculation
        FCV_LEFT_MOTOR_SPEED = 50;
        FCV_RIGHT_MOTOR_SPEED = 50;

      } else {

        // Calculation
        FCV_LEFT_MOTOR_SPEED = 50;
        FCV_RIGHT_MOTOR_SPEED = -50;

      }

    } else {

      // Calculation
      FCV_LEFT_MOTOR_SPEED = -50;
      FCV_RIGHT_MOTOR_SPEED = 50;
      FCV_COUNT = 100;

    }

    // Call Macro
    FCD_0dcd1_FormulaAllcode1__SetMotors(FCV_LEFT_MOTOR_SPEED, FCV_RIGHT_MOTOR_SPEED);

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDClear();

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintNumber(FCV_RIGHT, 2, 0, 0);

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintNumber(FCV_LEFT, 2, 64, 0);

    // Call Component Macro
    FCD_0dcd1_FormulaAllcode1__LCDPrintNumber(FCL_THRESH, 3, 0, 0);

    // Call Component Macro
    FCL_SW = FCD_0dcd1_FormulaAllcode1__ReadSwitch(1);

    // Decision
    if (FCL_SW)
    {    

      // Calculation
      FCL_THRESH = FCL_THRESH - 10;

      // Delay
      FCI_DELAYBYTE_MS(20);

    // } else {

    }

    // Call Component Macro
    FCL_SW = FCD_0dcd1_FormulaAllcode1__ReadSwitch(0);

    // Decision
    if (FCL_SW)
    {    

      // Calculation
      FCL_THRESH = FCL_THRESH + 10;

      // Delay
      FCI_DELAYBYTE_MS(20);

    // } else {

    }

    // Delay
    FCI_DELAYBYTE_MS(5);

  }

}

/*=----------------------------------------------------------------------=*\
   Use :Parameters for macro Increment_idx:
       :  idx : MX_UINT16
       :
       :Returns : MX_UINT16
\*=----------------------------------------------------------------------=*/
MX_UINT16 FCM_Increment_idx(MX_UINT16 FCL_IDX)
{
  //Local variable definitions
  MX_UINT8 FCL_EOF;
  MX_UINT16 FCR_RETVAL;


  // Assign incremented value to return variable
  FCR_RETVAL = FCL_IDX + 1;

  // If we are at the end of the sector
  if (FCL_IDX + 1 == 512)
  {  

    // Call Component Macro
    FCL_EOF = FCD_07fa1_FAT1__MoveToNextFileSector(0);

    // Decision
    if (FCL_EOF)
    {    

      // Calculation
      FCR_RETVAL = 512;

    } else {

      // Calculation
      FCR_RETVAL = 0;

    }

  // } else {

  }

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Parameters for macro Display_BMP:
       :  filename[20] : MX_CHAR
       :  X : MX_UINT16
       :  Y : MX_UINT16
       :
       :Returns : MX_UINT8
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_Display_BMP(MX_CHAR *PFCL_FILENAME, MX_UINT16 FCL_X, MX_UINT16 FCL_Y)
{
  //Local variable definitions
  MX_UINT8 FCL_RETVAL;
  MX_SINT16 FCL_IDX;
  MX_UINT16 FCL_DATA_OFFSET = (0x0);
  MX_UINT16 FCL_WIDTH = (0x0);
  MX_UINT16 FCL_HEIGHT;
  MX_UINT16 FCL_HEADER_FIELD;
  MX_UINT8 FCL_BITS_PER_PIXEL;
  MX_UINT8 FCL_COMPRESSION;
  MX_UINT16 FCL_WIDTH_IDX;
  MX_UINT8 FCL_B;
  MX_UINT8 FCL_TEST;
  MX_UINT8 FCR_RETVAL;

  #define FCLsz_FILENAME 20
  MX_CHAR FCL_FILENAME[FCLsz_FILENAME];
  FCI_CONCATENATE(PFCL_FILENAME,FCLsz_FILENAME,"",0,FCL_FILENAME,FCLsz_FILENAME);


  // Open File
  FCL_RETVAL = FCD_07fa1_FAT1__OpenFile(FCL_FILENAME, FCLsz_FILENAME);

  // Confirm File Opened
  if (FCL_RETVAL == 0)
  {  

    // Read Header Field
    FCL_HEADER_FIELD = FCM_Read_2_Byte_Packet(0);

    // Confirm "BM" file format
    if (FCL_HEADER_FIELD == ('M' << 8) | 'B')
    {    

      // Read Data Offset
      FCL_DATA_OFFSET = FCM_Read_4_Byte_Packet(0x0A);

      // Read pixel width
      FCL_WIDTH = FCM_Read_4_Byte_Packet(0x12);

      // Read pixel height
      FCL_HEIGHT = FCM_Read_4_Byte_Packet(0x16);

      // Read pixel data format
      FCL_BITS_PER_PIXEL = FCM_Read_2_Byte_Packet(0x1C);

      // Read pixel data format
      FCL_COMPRESSION = FCM_Read_4_Byte_Packet(0x1E);

      // Check we can read the data
      if ((FCL_BITS_PER_PIXEL == 1) && (FCL_COMPRESSION == 0))
      {      

        // Move to sector containing start of pixel data
        while (FCL_DATA_OFFSET > 511)
        {
          // Call Component Macro
          FCD_07fa1_FAT1__MoveToNextFileSector(0);

          // Calculation
          FCL_DATA_OFFSET = FCL_DATA_OFFSET - 512;

        }

        // Initialise idx to start of data
        FCL_IDX = FCL_DATA_OFFSET;

        //Comment:
        //BMP files run from left to right 
        //working upwards a row at a time
        //from bottom to top.

        // Loop through data
        while (FCL_HEIGHT > 0)
        {
          // Reset Row Idx
          FCL_WIDTH_IDX = 0;

          // Read and Print a row
          while (FCL_WIDTH > FCL_WIDTH_IDX)
          {
            // EOF?
            if (FCL_IDX == 512)
            {            

              // Goto Connection Point
              goto FCC_Display_BMP_A;

            // } else {

            }

            // Read Blue Data Byte
            FCL_B = FCD_07fa1_FAT1__ReadByteFromBuffer(FCL_IDX);

            // Call Macro
            FCL_IDX = FCM_Increment_idx(FCL_IDX);

            // Loop
            for (FCLV_LOOP5=0; (FCLV_LOOP5)<(8); (FCLV_LOOP5)++)
            {
              // Calculation
              FCL_TEST = FCL_B & 0x80;
              FCL_B = FCL_B << 1;

              // Decision
              if (FCL_TEST)
              {              

                // Call Component Macro
                FCD_0dcd1_FormulaAllcode1__LCDSetForegroundColour(0);

                // Print Pixel
                FCD_0dcd1_FormulaAllcode1__LCDPlotPixel(FCL_X + FCL_WIDTH_IDX, FCL_Y + (FCL_HEIGHT - 1));

              } else {

                // Call Component Macro
                FCD_0dcd1_FormulaAllcode1__LCDSetForegroundColour(1);

                // Print Pixel
                FCD_0dcd1_FormulaAllcode1__LCDPlotPixel(FCL_X + FCL_WIDTH_IDX, FCL_Y + (FCL_HEIGHT - 1));

              }

              // Move to next pixel in row
              FCL_WIDTH_IDX = FCL_WIDTH_IDX + 1;

              // Decision
              if (FCL_WIDTH_IDX == FCL_WIDTH)
              {              

                // Goto Connection Point
                goto FCC_Display_BMP_B;

              // } else {

              }

            }

            // Connection Point
          FCC_Display_BMP_B:
            ;

          }

          // Row data always ends 32-bit aligned
          while ((FCL_WIDTH_IDX % 32) != 0)
          {
            // Decision
            if ((FCL_WIDTH_IDX % 8) == 0)
            {            

              // Call Macro
              FCL_IDX = FCM_Increment_idx(FCL_IDX);

              // Decision
              if (FCL_IDX == 512)
              {              

                // Goto Connection Point
                goto FCC_Display_BMP_A;

              // } else {

              }

            // } else {

            }

            // Calculation
            FCL_WIDTH_IDX = FCL_WIDTH_IDX + 1;

          }

          // Move to next row
          FCL_HEIGHT = FCL_HEIGHT - 1;

        }

        // Connection Point
      FCC_Display_BMP_A:
        ;

        // Calculation
        FCR_RETVAL = 0;

      } else {

        // Calculation
        FCR_RETVAL = 255;

      }

    } else {

      // Calculation
      FCR_RETVAL = 255;

    }

  } else {

    // Calculation
    FCR_RETVAL = 239;

  }

  // Call Component Macro
  FCD_0dcd1_FormulaAllcode1__LCDSetForegroundColour(FCV_LCDFORECOL);

  return (FCR_RETVAL);

  //Local variable definitions
  #undef FCLsz_FILENAME
}

